import type { Metadata } from "next";
import { site } from "@/content/site";
import { education, certifications } from "@/content/experience";

/** Absolute URL on the canonical domain (no trailing slash except the homepage). */
export const absUrl = (path: string) => (path === "/" ? site.url : `${site.url}${path}`);

/** Social share image (generated by app/opengraph-image.tsx), attached to every page. */
const SHARE_IMAGE = { url: "/opengraph-image", width: 1200, height: 630, alt: "Agman Rajpurohit, SEO specialist in Dubai" };

/**
 * Per-page metadata: title, description, absolute canonical, and Open Graph / X cards.
 * `socialTitle` lets the share card read a little differently from the search title.
 */
export function pageMeta({
  title,
  description,
  path,
  socialTitle,
  absoluteTitle,
}: {
  title: string;
  description: string;
  path: string;
  socialTitle?: string;
  absoluteTitle?: boolean;
}): Metadata {
  const url = absUrl(path);
  const share = socialTitle ?? title;
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: url },
    openGraph: {
      title: share,
      description,
      url,
      siteName: site.name,
      type: path === "/" ? "profile" : "website",
      locale: "en_AE",
      images: [SHARE_IMAGE],
      ...(path === "/" ? { firstName: site.firstName, lastName: site.lastName } : {}),
    },
    twitter: { card: "summary_large_image", title: share, description, images: [SHARE_IMAGE.url] },
  };
}

/** WebPage-family node tied to the site and to Agman, for each page's JSON-LD. */
export function webPageJsonLd({
  type = "WebPage",
  name,
  description,
  path,
}: {
  type?: "WebPage" | "ProfilePage" | "ContactPage" | "CollectionPage" | "AboutPage";
  name: string;
  description: string;
  path: string;
}) {
  const url = absUrl(path);
  return {
    "@context": "https://schema.org",
    "@type": type,
    "@id": `${url}#webpage`,
    url,
    name,
    description,
    inLanguage: "en",
    isPartOf: { "@id": `${site.url}/#website` },
    about: { "@id": `${site.url}/#person` },
    ...(type === "ProfilePage" ? { mainEntity: { "@id": `${site.url}/#person` } } : {}),
    primaryImageOfPage: { "@type": "ImageObject", url: `${site.url}/opengraph-image` },
  };
}

/** Person + WebSite structured data, describing Agman as one consistent entity. */
export function personJsonLd() {
  const id = `${site.url}/#person`;
  return {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "Person",
        "@id": id,
        name: site.name,
        givenName: site.firstName,
        familyName: site.lastName,
        jobTitle: site.role,
        description:
          "SEO specialist in Dubai with hands-on experience in technical, local and ecommerce SEO, content for AI search, Google and Meta ads, and WordPress development.",
        url: site.url,
        mainEntityOfPage: { "@id": `${site.url}/#webpage` },
        workLocation: { "@type": "Place", name: "Dubai, United Arab Emirates" },
        image: `${site.url}${site.photo}`,
        email: `mailto:${site.email}`,
        telephone: site.locations[0].phone.replace(/\s/g, ""),
        nationality: { "@type": "Country", name: "India" },
        address: { "@type": "PostalAddress", addressLocality: "Dubai", addressCountry: "AE" },
        sameAs: [site.linkedin],
        knowsAbout: [
          "Search Engine Optimization",
          "Technical SEO",
          "Local SEO",
          "International SEO",
          "Ecommerce SEO",
          "Generative Engine Optimization",
          "Answer Engine Optimization",
          "Google Ads",
          "Meta Ads",
          "Google Business Profile",
          "Schema markup",
          "WordPress development",
        ],
        alumniOf: { "@type": "CollegeOrUniversity", name: education.school },
        hasCredential: certifications.map((c) => ({
          "@type": "EducationalOccupationalCredential",
          name: c.name,
          recognizedBy: { "@type": "Organization", name: c.issuer },
        })),
        hasOccupation: {
          "@type": "Occupation",
          name: site.role,
          occupationLocation: { "@type": "City", name: "Dubai" },
          skills: "SEO, GEO, AEO, Technical SEO, Local SEO, Google Ads, Meta Ads, WordPress",
        },
      },
      {
        "@type": "WebSite",
        "@id": `${site.url}/#website`,
        url: site.url,
        name: site.name,
        alternateName: "Agman Rajpurohit SEO",
        description: "Portfolio, case studies and a free website SEO audit tool by Agman Rajpurohit.",
        inLanguage: "en",
        publisher: { "@id": id },
      },
    ],
  };
}

export function breadcrumbJsonLd(items: { name: string; path: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: items.map((it, i) => ({
      "@type": "ListItem",
      position: i + 1,
      name: it.name,
      item: absUrl(it.path),
    })),
  };
}
